typedef struct MemoryPool {
    void *pool_start;
    size_t block_size;
    size_t total_blocks;
    unsigned char *free_list;
} MemoryPool;

void init_memory_pool(MemoryPool *mp, size_t block_size, size_t total_blocks) {
    mp->pool_start = malloc(block_size * total_blocks);
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->free_list = calloc(1, total_blocks); // 0 indicates free
}

void *custom_alloc(MemoryPool *mp) {
    for (size_t i = 0; i < mp->total_blocks; ++i) {
        if (mp->free_list[i] == 0) {
            mp->free_list[i] = 1;
            return (char*)mp->pool_start + i * mp->block_size;
        }
    }
    return NULL; // No free blocks
}

void custom_free(MemoryPool *mp, void *ptr) {
    size_t index = ((char*)ptr - (char*)mp->pool_start) / mp->block_size;
    if (index < mp->total_blocks) {
        mp->free_list[index] = 0;
    }
}

// Usage
MemoryPool myPool;
init_memory_pool(&myPool, 64, 100); // 100 blocks of 64 bytes
void *block = custom_alloc(&myPool);
// ... use the block ...
custom_free(&myPool, block);
